const ptak = { imie: "Kiwi", odezwijSieArrow: () => console.log(this) };

ptak.odezwijSieArrow();
// this jest undefined (w module ES) - arrow function NIE ma wlasnego this,
// wiec dziedziczy je z zewnetrznego, otaczajacego zasiegu (poziom modulu),
// a NIE z obiektu ptak, mimo ze jest jego "metoda".

const zegar = {
  godzina: 0,
  startArrow() {
    setTimeout(() => {
      this.godzina++;
      console.log(this.godzina);
    }, 10);
  },
};

zegar.startArrow(); // po 10ms wypisze 1 - this poprawnie === zegar

const zegar2 = {
  godzina: 0,
  startZwykla() {
    setTimeout(function () {
      // this.godzina++; -- BY NIE ZADZIALALO
    }, 10);
  },
};

zegar2.startZwykla();
// Zwykla funkcja (nie arrow) przekazana jako callback do setTimeout MA
// WLASNE this, ktore NIE jest zwiazane z zegar2 - setTimeout wywoluje ja
// samodzielnie, wiec this wewnatrz bylby undefined, a this.godzina++
// rzucilby blad proby odczytu wlasciwosci z undefined.

const gracz = {
  punkty: 0,
  dodajPunktyPoCzasie() {
    setTimeout(() => {
      this.punkty += 10;
      console.log(this.punkty);
    }, 5);
  },
};

gracz.dodajPunktyPoCzasie(); // po 5ms wypisze 10

const magazyn = {
  produkty: ["but", "kurtka"],
  iloscArrow: () => this,
  iloscZwykla() {
    return this.produkty.length;
  },
};

console.log(magazyn.iloscArrow());  // undefined - arrow gubi zwiazek z magazyn
console.log(magazyn.iloscZwykla()); // 2 - zwykla metoda dziala poprawnie

const kolejka = {
  zadania: [],
  dodajZOpoznieniem(zadanie) {
    setTimeout(() => {
      this.zadania.push(zadanie);
      console.log(this.zadania);
    }, 5);
  },
};

kolejka.dodajZOpoznieniem("wyslij email"); // po 5ms: ["wyslij email"]

const stoper = {
  czas: 0,
  start() {
    const zwiekszCzas = () => {
      this.czas++;
    };
    zwiekszCzas();
    zwiekszCzas();
  },
};

stoper.start();
console.log(stoper.czas); // 2

const przyklad = {
  wartosc: 42,
  // BLAD: arrow function bezposrednio jako metoda - this ucieka na zewnatrz
  zlaMetoda: () => this.wartosc,
  // POPRAWNIE: zwykla metoda tworzy wlasne this === przyklad,
  // arrow function WEWNATRZ niej dziedziczy TO poprawne this
  dobraMetoda() {
    const pobierz = () => this.wartosc;
    return pobierz();
  },
};

console.log(przyklad.zlaMetoda());  // undefined
console.log(przyklad.dobraMetoda()); // 42
// Roznica polega na tym, GDZIE arrow function zostaje ZDEFINIOWANA.
// zlaMetoda jest zdefiniowana BEZPOSREDNIO w literale obiektu {} - obiekt
// literalowy NIE tworzy wlasnego zasiegu this, wiec this "ucieka" na
// poziom modulu (undefined). pobierz wewnatrz dobraMetoda jest
// zdefiniowana WEWNATRZ zwyklej metody, ktora MA wlasne, poprawne this
// (=== przyklad) - arrow function to this dziedziczy.
